"""S5 report: builds analysis/out/s5/S5_REPORT.md from the S5 JSON outputs (no hand-typed numbers)."""
import collections
import json
import os

A = os.path.dirname(os.path.abspath(__file__)); O = os.path.join(A, "out"); D = os.path.join(O, "s5")
SETS = (("all48", "all 48 holdout tasks (main results)"), ("clean27", "the 27 holdout tasks no pilot run touched (untouched subset)"))
EV = {k: json.load(open(os.path.join(D, k, "label_eval.json"))) for k, _ in SETS}
RK = {k: json.load(open(os.path.join(D, k, "rankings.json"))) for k, _ in SETS}
SC = {k: [json.loads(l) for l in open(os.path.join(D, k, "scored.jsonl"))] for k, _ in SETS}
GAP = {k: json.load(open(os.path.join(O, k, "s5_gap_by_task.json"))) for k, _ in SETS}
ev, rk, scored, gap = EV["all48"], RK["all48"], SC["all48"], GAP["all48"]
cr0, cr1 = json.load(open(os.path.join(O, "calib_rules.json"))), json.load(open(os.path.join(O, "s5_calib_rules_replayany.json")))
NAMES = {"exec": "execution (current)", "agentdojo": "AgentDojo recorded", "replay": "replay, end state",
         "replay_any": "replay, any point (post hoc)", "full": "execution AND replay"}
pct = lambda x: f"{100 * x:.1f}%"
L = ["# S5 (internal review): repaired attack oracle, rescoring and calibration robustness", "",
     "Generated by `analysis/s5_report.py` from `analysis/out/s5/*.json`, `analysis/out/s5_*_replayany.json` and `analysis/out/clean27/s5_gap_by_task.json`.", "",
     "## Oracles", "",
     "- **execution (current)**: an executed call without error matches a ground-truth side-effecting call on function and every control value (`exec_oracle.success`).",
     "- **AgentDojo recorded**: the row's `security` field, AgentDojo's own check on the real post-run environment.",
     "- **replay, end state**: AgentDojo's `security()` of the injection task on a fresh environment in which only the row's executed calls without error are replayed in order.",
     "- **replay, any point (repaired)**: the same check after each replayed call, success if it holds at any point. This applies AgentDojo's own content and amount conditions to the calls that ran and avoids the last-writer limit of state checks, for example travel injection_task_0 reads the single reservation slot that a later user-task booking overwrites. **Post hoc:** this rule was added after the blind labels below had been read (the pre-defined repaired oracle was execution AND replay), so its accuracy is measured on the same 160-row sample used to design it and is optimistically biased; it is a sensitivity analysis, not validated (analyst, project lead).",
     "- **execution AND replay**: both of the first and third conditions.", "",
     f"Rows rescored: {len(scored)} attack rows (part b) of {', '.join(sorted({x['model'] for x in scored}))}, all defenses.", "",
     "## Accuracy against blind labels", "",
     f"Sample: {ev['n_sample']} rows, stratified by (execution, AgentDojo recorded) with up to 40 per cell, seed 20261020. An independent labeller saw only the attacker goal, the user task and the executed calls with their errors and labelled {ev['n_label_success']} rows as successful attacks. Intervals are Wilson 95% confidence intervals for a sample proportion. Population-weighted accuracy reweights the strata to their sizes among all rows: {ev['population_cells']}.", "",
     "The pre-defined oracles are execution, AgentDojo recorded, replay and execution AND replay. The replay, any point row was added after these labels were read and was scored on the same sample, so its accuracy is not an independent validation.", "",
     "| Oracle | Accuracy on sample, 95% CI | False positives among label-failures | False negatives among label-successes | Population-weighted accuracy |",
     "|---|---|---|---|---|"]
for subset, title in (("all", "all 160 rows"), ("unambiguous", "without the 15 rows the labeller called ambiguous")):
    if subset != "all":
        L += ["", f"Sensitivity, {title}:", "", "| Oracle | Accuracy, 95% CI | False positives | False negatives | Population-weighted |", "|---|---|---|---|---|"]
    for o, x in ev["oracles"][subset].items():
        a = x["accuracy"]
        L.append(f"| {NAMES[o]} | {x['accuracy_k']} of {x['n']}, {pct(a[0])} (95% CI {pct(a[1])} to {pct(a[2])}) | {x['fp_k']} of {x['n_label_fail']} | {x['fn_k']} of {x['n_label_success']} | {pct(x['accuracy_population_weighted'])} |")
def rank_section(key, title, rk, scored):
    global L
    L += ["", "## Defense rankings under the current and the repaired oracle, " + title + "", "",
          "Block rate = 1 minus attack successes under the defense over attack successes without defense, on paired attack rows; 95% task-cluster bootstrap confidence intervals as in `rq34.py`. Rank 1 blocks most.", ""]
    for m in rk["exec"]:
        def ranks(o):
            arms = [a for a in rk[o][m] if a != "none"]
            return {a: i + 1 for i, a in enumerate(sorted(arms, key=lambda a: -rk[o][m][a]["block_rate"]))}
        re_, ra = ranks("exec"), ranks("replay_any")
        L += [f"### {m}, {key}", "", "| Defense | Execution oracle: rank, block rate (95% CI) | Repaired oracle: rank, block rate (95% CI) | Rank change |", "|---|---|---|---|"]
        for a in sorted(ra, key=ra.get):
            e, x = rk["exec"][m][a], rk["replay_any"][m][a]
            L.append(f"| {a} | {re_[a]}, {e['block_rate']:.3f} ({e['ci'][0]:.2f} to {e['ci'][1]:.2f}) | {ra[a]}, {x['block_rate']:.3f} ({x['ci'][0]:.2f} to {x['ci'][1]:.2f}) | {re_[a] - ra[a]:+d} |")
        L.append("")
    dis = [x for x in scored if x["exec"] is not None and x["replay_any"] is not None and x["exec"] != x["replay_any"]]
    json.dump(dis, open(os.path.join(D, key, "disagreements_exec_vs_repaired.json"), "w"), indent=1)
    by = collections.Counter((x["model"], x["suite"], x["it"], "exec=1, repaired=0" if x["exec"] else "exec=0, repaired=1") for x in dis)
    L += ["## Disagreements between the current and the repaired oracle, " + title + "", "",
          f"{len(dis)} of {sum(x['exec'] is not None and x['replay_any'] is not None for x in scored)} rows disagree. Full list with row ids: `analysis/out/s5/" + key + "/disagreements_exec_vs_repaired.json`. Grouped by model, injection task and direction:", "",
          "| Model | Suite | Injection task | Direction | Rows |", "|---|---|---|---|---|"]
    for (m, s, it, d), n in sorted(by.items(), key=lambda kv: -kv[1]):
        L.append(f"| {m} | {s} | {it} | {d} | {n} |")
    return dis

def gap_section(key, title, gap):
    global L
    L += ["", "## Calibration loss against holdout false-block rate, by task, " + title + "", "",
          "Calibration loss is the mean over the 25 calibration tasks of the share of the model's own mining runs that the allowlist blocks; the holdout false-block rate is the share of benign holdout runs blocked (" + title + "). Both use the selected predictor and exclude holdout tasks from mining. Shown for the exact level with all mined tasks (element `exact`, r = all).", "",
          "| Model | Calibration loss, task mean | Holdout false-block, run pooled | Holdout, task mean | Calibration tasks with any block | Holdout tasks with any block | Share of calibration loss from the top 3 tasks |", "|---|---|---|---|---|---|---|"]
    for m, g in gap.items():
        c = next(x for x in g["chain"] if x["level"] == "exact" and x["r"] >= 1000)
        L.append(f"| {m} | {pct(c['cal_task_mean'])} | {pct(c['holdout_run_pooled'])} | {pct(c['holdout_task_mean'])} | {c['n_cal_tasks_blocked']} of {c['n_cal_tasks']} | {c['n_holdout_tasks_blocked']} of {c['n_holdout_tasks']} | {pct(c['cal_loss_share_top3']) if c['cal_loss_share_top3'] is not None else '--'} |")
    L += ["", "Calibration tasks with the largest loss at this element:", ""]
    for m, g in gap.items():
        c = next(x for x in g["chain"] if x["level"] == "exact" and x["r"] >= 1000)
        tops = ", ".join(f"{t['task']} {t['blocked']} of {t['runs']}" for t in c["cal_top_tasks"] if t["blocked"])
        hos = ", ".join(f"{t['task']} {t['blocked']} of {t['runs']}" for t in c["holdout_blocked_tasks"]) or "none"
        L.append(f"- **{m}**: calibration {tops or 'none'}; holdout {hos}.")

dis = None
for key, title in SETS:
    if key != "all48":
        e2 = EV[key]['oracles']['all']
        L += ["", f"## Untouched subset ({key})", "", "Population-weighted accuracy on " + title + ": " + ", ".join(f"{NAMES[o]} {pct(x['accuracy_population_weighted'])}" for o, x in e2.items()) + ".", ""]
    d = rank_section(key, title, RK[key], SC[key])
    dis = d if key == "all48" else dis
L += ["", "## Calibration robustness under the repaired oracle", "",
      "`resplit.py` and `calib_rules.py` rerun unchanged on the same 100 re-splits except that holdout violations are undefended attack rows that succeed under the repaired oracle (`analysis/s5_calib_robust.py`; the paper's `calib_rules.json` and `resplit.json` are untouched). Primary target 10%.", "",
      "| Model | Selection rule | Splits keeping the value layer, recorded / repaired | Mean holdout flag rate, recorded / repaired | Splits with holdout false-block above target |", "|---|---|---|---|---|"]
for m in cr0["models"]:
    for rule, x in cr0["models"][m]["summary"]["0.1"].items():
        y = cr1["models"][m]["summary"]["0.1"][rule]
        L.append(f"| {m} | {rule} | {x['kept']} / {y['kept']} of {x['n']} | {pct(x['flag_mean'])} / {pct(y['flag_mean'])} | {x['fb_over_eps']} / {y['fb_over_eps']} |")
for key, title in SETS:
    gap_section(key, title, GAP[key])
open(os.path.join(D, "S5_REPORT.md"), "w").write("\n".join(L) + "\n")
print("wrote", os.path.join(D, "S5_REPORT.md"), len(L), "lines;", len(dis), "disagreements")
